package com.alsafa.native4;

import android.app.Activity;import android.app.AlertDialog;import android.graphics.Color;import android.text.InputType;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.OnlineSaleSettlementStore;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Online orders. Customer-paid carrier shipping stays outside AlSafa books; only AlSafa-paid shipping is entered as an expense. */
public final class OnlineSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final LinearLayout panel,initialRows,collectRows;private final EditText saleId,merchandise,ourShipping,settlementId,expenseAmount,expenseType,expenseNotes,finalPrice,adjustReason;private final Spinner merchandiseCurrency,ourShippingCurrency,ourShippingAccount,expenseCurrency,expenseAccount;
 public OnlineSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);title("بيع الإنترنت — قيمة الطلب والتحصيل");saleId=field("مرجع فاتورة البيع",InputType.TYPE_CLASS_TEXT);merchandise=field("قيمة الساعات / المنتجات فقط",numType());merchandiseCurrency=currency();add(saleId,merchandise,merchandiseCurrency);TextView shippingInfo=new TextView(a);shippingInfo.setText("الشحن على العميل: لا تسجله هنا؛ شركة الشحن تقبضه مباشرة. املأ الحقول التالية فقط إذا كان الشحن على الصفا.");shippingInfo.setGravity(Gravity.END);panel.addView(shippingInfo);ourShipping=field("أجرة الشحن علينا (اتركها فارغة عادةً)",numType());ourShippingCurrency=currency();ourShippingAccount=account(false);add(ourShipping,ourShippingCurrency,ourShippingAccount);title("العربون / الدفعات الأولية");initialRows=rows();button("+ إضافة دفعة",v->addPayment(initialRows));addPayment(initialRows);button("تثبيت تسوية بيع الإنترنت",v->create());title("تحصيل لاحق");settlementId=field("مرجع التسوية",InputType.TYPE_CLASS_TEXT);panel.addView(settlementId);collectRows=rows();addPayment(collectRows);button("+ إضافة دفعة تحصيل",v->addPayment(collectRows));button("تسجيل التحصيل",v->collect());title("مصروف آخر على الطلب");expenseType=field("نوع المصروف: تغليف / توصيل إضافي / غيره",InputType.TYPE_CLASS_TEXT);expenseAmount=field("قيمة المصروف",numType());expenseCurrency=currency();expenseAccount=account(false);expenseNotes=field("ملاحظات المصروف",InputType.TYPE_CLASS_TEXT);add(expenseType,expenseAmount,expenseCurrency,expenseAccount,expenseNotes);button("تسجيل المصروف",v->expense());title("تعديل السعر النهائي بعد المفاصلة");finalPrice=field("السعر النهائي للمنتجات",numType());adjustReason=field("سبب التعديل",InputType.TYPE_CLASS_TEXT);add(finalPrice,adjustReason);button("تعديل السعر النهائي",v->confirmAdjust());host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}private void create(){try{String mc=code(merchandiseCurrency);double ship=num(ourShipping);OnlineSaleSettlementStore.Result r=services.onlineSales.create(saleId.getText().toString(),num(merchandise),mc,0,mc,false,read(initialRows),"UNPAID","CARRIER","");settlementId.setText(r.settlementId);if(ship>0)services.onlineSales.addExpense(r.settlementId,"SHIPPING",ship,code(ourShippingCurrency),"ALSAFA",accountCode(ourShippingAccount.getSelectedItemPosition()),"الشحن على الصفا");sync();status.setText("✓ تم إنشاء الطلب — قيمة منتجات الصفا "+fmt(r.totalDueUsd)+" USD — المدفوع "+fmt(r.paidTotalUsd)+" — المتبقي "+fmt(r.remainingUsd)+(ship>0?" — وسُجل الشحن علينا كمصروف":""));}catch(Exception e){error("لم يُحفظ طلب الإنترنت",e);}}
 private void collect(){try{OnlineSaleSettlementStore.Result r=services.onlineSales.collect(settlementId.getText().toString(),read(collectRows));sync();collectRows.removeAllViews();addPayment(collectRows);status.setText("✓ التحصيل — المدفوع "+fmt(r.paidTotalUsd)+" USD — المتبقي "+fmt(r.remainingUsd));}catch(Exception e){error("لم يُحفظ التحصيل",e);}}
 private void expense(){try{String id=services.onlineSales.addExpense(settlementId.getText().toString(),expenseType.getText().toString(),num(expenseAmount),code(expenseCurrency),"ALSAFA",accountCode(expenseAccount.getSelectedItemPosition()),expenseNotes.getText().toString());sync();expenseAmount.setText("");status.setText("✓ تم تسجيل مصروف الطلب — "+id);}catch(Exception e){error("لم يُحفظ المصروف",e);}}
 private void confirmAdjust(){try{double p=num(finalPrice);String why=adjustReason.getText().toString().trim();if(why.isEmpty())throw new IllegalArgumentException("سبب تعديل السعر مطلوب");new AlertDialog.Builder(a).setTitle("تأكيد تعديل السعر").setMessage("سيتم تغيير السعر النهائي للمنتجات إلى "+fmt(p)+" بعملة الفاتورة، وسيُسجل الفرق كحسم للعميل أو زيادة. الدفعات الجزئية لا تُسجل من هنا. هل تريد المتابعة؟").setNegativeButton("رجوع",null).setPositiveButton("تأكيد",(d,w)->adjust(p,why)).show();}catch(Exception e){error("تعذر تعديل السعر",e);}}
 private void adjust(double p,String why){try{OnlineSaleSettlementStore.Result r=services.onlineSales.adjustFinalMerchandisePrice(settlementId.getText().toString(),p,true,why);sync();status.setText("✓ السعر النهائي عُدّل — النوع "+r.adjustmentKind+" — الحسم "+fmt(r.customerDiscount)+" — المتبقي "+fmt(r.remainingUsd)+" USD");}catch(Exception e){error("لم يُعدل السعر",e);}}
 private void addPayment(LinearLayout host){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field("المبلغ",numType());Spinner cur=currency(),acc=account(false);Button del=new Button(a);del.setText("حذف الدفعة");del.setOnClickListener(v->{if(host.getChildCount()>1)host.removeView(box);else amount.setText("");});box.addView(amount);box.addView(cur);box.addView(acc);box.addView(del);box.setTag(new PV(amount,cur,acc));host.addView(box);}private List<SplitPaymentStore.Payment> read(LinearLayout host){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<host.getChildCount();i++){PV p=(PV)host.getChildAt(i).getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;String cur=code(p.currency),acc=accountCode(p.account.getSelectedItemPosition()),method="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(Double.parseDouble(raw),cur,method,acc));}return out;}
 private LinearLayout rows(){LinearLayout x=new LinearLayout(a);x.setOrientation(LinearLayout.VERTICAL);panel.addView(x);return x;}private Spinner currency(){return spinner(AccountingChoices.CURRENCY_LABELS);}private Spinner account(boolean ignored){return spinner(new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"});}private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private String code(Spinner s){return AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,s.getSelectedItemPosition());}
 private void title(String s){TextView t=new TextView(a);t.setText(s);t.setTextSize(18);t.setGravity(Gravity.END);t.setPadding(0,dp(16),0,dp(8));panel.addView(t);}private void button(String s,View.OnClickListener l){Button b=new Button(a);b.setText("✓ "+s);b.setTextColor(Color.WHITE);b.setTextSize(17);b.setMinHeight(dp(58));b.setBackgroundResource(R.drawable.alsafa_primary);b.setOnClickListener(l);panel.addView(b);}private void add(View...vs){for(View v:vs)panel.addView(v);}private EditText field(String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setMinHeight(dp(54));e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackgroundResource(R.drawable.alsafa_card);e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private Spinner spinner(String[] labels){Spinner s=new Spinner(a);s.setMinimumHeight(dp(54));s.setBackgroundResource(R.drawable.alsafa_card);s.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));return s;}private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static int numType(){return InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL;}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private void sync(){Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();}private void error(String p,Exception e){status.setText(p+": "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static final class PV{final EditText amount;final Spinner currency,account;PV(EditText a,Spinner c,Spinner x){amount=a;currency=c;account=x;}}
}
